"""An HTTP function that quotes a delivery fee, written for Google Cloud's Functions Framework.

Run it locally:  functions-framework --target=quote --port=8080
Then call it:    curl "http://localhost:8080/?distance_km=12"
"""
import functions_framework

BASE_FEE = 2.5      # in credits, a made-up unit for this course
PER_KM = 0.8


@functions_framework.http
def quote(request):
    """request is a Flask request; the return value becomes the HTTP response."""
    try:
        km = float(request.args.get("distance_km", ""))
    except ValueError:
        return {"error": "distance_km must be a number"}, 400
    # TODO: reject distances of zero or less, and over 50 km, with a 400 response and an error message.
    return {"distance_km": km, "fee": round(BASE_FEE + PER_KM * km, 2), "unit": "credits"}
